H.background();
const c = P.conc;
const b = P.path;
const eps = 200;
const A = eps * b * c;
const Ttrans = Math.pow(10, -A);
const v = H.plot2d({ xMin: 0, xMax: 0.02, yMin: 0, yMax: 4 });
v.grid(); v.axes();
const slope = eps * b;
v.fn(x => slope * x, { color: H.colors.accent, width: 3 });
const cc = Math.min(0.02, Math.max(0, c * (0.6 + 0.4 * Math.sin(t * 1.0))));
const Ac = slope * cc;
v.dot(cc, Math.min(Ac, 4), { r: 7, fill: H.colors.yellow });
v.text("slope = ε·b", 0.001, 3.5);
const cx = 760, cy = 300, cw = 70, ch = 150;
H.rect(cx - cw/2, cy - ch/2, cw, ch, { stroke: H.colors.axis, width: 2 });
const shade = Math.min(1, A / 4);
H.rect(cx - cw/2 + 2, cy - ch/2 + 2, cw - 4, ch - 4, { fill: H.hsl(280, 70, 50, 0.2 + 0.7 * shade) });
H.line(cx - cw, cy, cx - cw/2, cy, { color: H.colors.yellow, width: 3 });
H.line(cx + cw/2, cy, cx + cw, cy, { color: H.colors.yellow, width: Math.max(1, 3 * Ttrans) });
const ph = ((t * 0.4) % 1);
H.circle(cx - cw + (cw/2) * ph, cy, 4, { fill: H.colors.yellow });
if (Ttrans > 0.05) H.circle(cx + cw/2 + (cw/2) * ph, cy, 4 * Ttrans + 1, { fill: H.colors.yellow });
H.text("I₀", cx - cw - 4, cy - 12, { color: H.colors.sub, size: 12, align: "right" });
H.text("I", cx + cw + 4, cy - 12, { color: H.colors.sub, size: 12 });
H.text("Beer–Lambert law:  A = ε·b·c", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Absorbance is linear in concentration — basis of spectrophotometry", 24, 50, { color: H.colors.sub, size: 13 });
H.text("ε = " + eps + " L·mol⁻¹·cm⁻¹,  b = " + b.toFixed(2) + " cm,  c = " + c.toFixed(4) + " M", 24, 80, { color: H.colors.accent, size: 13 });
H.text("A = " + A.toFixed(2) + "   →   T = 10^(−A) = " + (Ttrans * 100).toFixed(1) + "%", 24, 100, { color: H.colors.good, size: 13 });
